INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(54747648, 'Green Turtle Summoner', '玄武召唤士', '玄武の召喚士', 'Effect Monster', 'Spellcaster', 'WATER', 3, 400, 1500, '①：这张卡反转的场合，以对方场上1只怪兽为对象发动。那只怪兽破坏。'),
(61831093, 'Greenkappa', '二重身', 'ドッペルゲンガー', 'Flip Effect Monster', 'Warrior', 'DARK', 3, 650, 900, '反转：选择场上盖放的2张魔法·陷阱卡破坏。'),
(36584821, 'Gren Maju Da Eiza', '红莲魔兽 泰沙', '紅蓮魔獣 ダ・イーザ', 'Effect Monster', 'Fiend', 'FIRE', 3, -1, -1, '①：这张卡的攻击力·守备力变成自己的除外状态的卡数量×400。'),
(51232472, 'Gren, Tactician of Dark World', '暗黑界的策士 格林', '暗黒界の策士 グリン', 'Effect Monster', 'Fiend', 'DARK', 2, 300, 500, '①：这张卡被效果从手卡丢弃去墓地的场合，以场上1张魔法·陷阱卡为对象发动。那张卡破坏。'),
(47506081, 'Grenosaurus', '红莲恐龙', 'グレンザウルス', 'XYZ Monster', 'Dinosaur', 'FIRE', 3, 2000, 1900, '3星怪兽×2 这张卡战斗破坏对方怪兽送去墓地时，可以把这张卡1个超量素材取除，给与对方基本分1000分伤害。'),
(34481518, 'Grenosaurus Giga-Cannon', '魔头炮 红莲恐龙', '魔頭砲グレンザウルス', 'XYZ Monster', 'Dinosaur', 'FIRE', 4, 2200, 2000, '4星怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：自己的恐龙族怪兽战斗破坏对方怪兽送去墓地时，把这张卡1个超量素材取除才能发动。给与对方1000伤害。那之后，这张卡的攻击力上升1000。 ②：超量召唤的这张卡被破坏的场合，以场上1张卡为对象才能发动。那张卡破坏，给与对方1000伤害。'),
(30552375, 'Grid Rod', '网格杖', 'グリッド・ロッド', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '自己场上的电子界族怪兽才能装备。 ①：装备怪兽的攻击力上升300，不受对方的效果影响，1回合只有1次不会被战斗破坏。 ②：场上的表侧表示的这张卡被破坏送去墓地的场合才能发动。自己场上的全部电子界族怪兽直到回合结束时不会被战斗·效果破坏。'),
(13090893, 'Grid Sweeper', '网格扫除机', 'グリッド・スィーパー', 'Effect Monster', 'Cyberse', 'LIGHT', 4, 100, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：场地魔法卡表侧表示存在的场合才能发动。这张卡从手卡特殊召唤。 ②：把墓地的这张卡以及自己场上1只连接怪兽除外才能发动。选对方场上1张卡破坏。'),
(18046862, 'Grief Tablet', '叹息石版', '嘆きの石版', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：装备怪兽不能攻击，效果无效化，不能解放。 ②：1回合1次，装备怪兽在自己场上存在的场合才能发动。从卡组把「叹息之石版」以外的1张「石版」卡加入手卡。 ③：装备怪兽被破坏让这张卡被送去墓地的场合才能发动。给与对方500伤害。'),
(53829412, 'Griffore', '狮鹫兽卫', 'グリフォール', 'Normal Monster', 'Beast', 'EARTH', 4, 1200, 1500, '善于用坚固的身体守备。将对方的攻击反弹。'),
(95744531, 'Griggle', '格里格尔', 'グリグル', 'Effect Monster', 'Plant', 'EARTH', 1, 350, 300, '场上表侧表示存在的这张卡的控制权转移给对方时，自己回复3000基本分。这个效果只在这张卡在场上表侧表示存在能使用1次。'),
(75732622, 'Grinder Golem', '拷问巨人', 'トーチ・ゴーレム', 'Effect Monster', 'Fiend', 'DARK', 8, 3000, 300, '这张卡不能通常召唤。通过在自己场上把2只「拷问衍生物」（恶魔族·暗·1星·攻/守0）攻击表示特殊召唤可以在对方场上特殊召唤。把这张卡特殊召唤的回合，自己不能通常召唤。'),
(75732623, 'Grinder Token', '拷问巨人', 'トーチ・ゴーレム', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(85555787, 'Grinning Grave Virus', '恶之卡组破坏病毒', '悪のデッキ破壊ウイルス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只攻击力3000以下的暗属性怪兽解放才能发动。那只怪兽的攻击力每有500，对方从自身的手卡·卡组选1张卡破坏。为这张卡发动而把攻击力2000以上的怪兽解放的场合，用对方回合计算的3回合内对方抽到的卡全部确认，那之内的怪兽全部破坏。此外，这张卡的效果破坏送去墓地的卡在破坏的回合不能把效果发动。'),
(22888900, 'Grisaille Prison', '纯灰色画的牢狱', 'グリザイユの牢獄', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有上级召唤·仪式召唤·融合召唤的怪兽之内任意种表侧表示存在的场合才能发动。直到下次的对方回合的结束时，双方不能进行同调·超量召唤，场上的同调·超量怪兽效果无效化，不能攻击。'),
(300202004, 'Grit', NULL, NULL, 'Skill Card', 'Joey', NULL, NULL, NULL, NULL, NULL),
(58314394, 'Ground Attacker Bugroth', '陆战型 战斗舰', '陸戦型 バグロス', 'Normal Monster', 'Machine', 'EARTH', 4, 1500, 1000, '陆地战斗机器人，总有一天能在海里使用。'),
(90502999, 'Ground Collapse', '地盘沉下', '地盤沈下', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '指定没有使用的主要怪兽区域2处才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，指定的区域不能使用。'),
(17243896, 'Ground Spider', '大地蜘蛛', 'グランド・スパイダー', 'Effect Monster', 'Insect', 'EARTH', 4, NULL, 1500, '这张卡在自己场上表侧守备表示存在的场合对方对怪兽的召唤·特殊召唤成功时，可以把那些怪兽变成守备表示。这个效果1回合只能使用1次。'),
(67523044, 'Ground Xeno', '地面异点', 'グラウンド・ゼノ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把1只恐龙族调整或者恐龙族通常怪兽加入手卡。那之后，选自己1张手卡破坏。 ②：把墓地的这张卡除外才能发动。从自己的手卡·场上把恐龙族融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。'),
(45420955, 'Groza, Tyrant of Thunder', '迅雷之暴君 格罗扎', '迅雷の暴君 グローザー', 'Synchro Monster', 'Fiend', 'DARK', 8, 2800, 2800, '调整＋调整以外的恶魔族怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：对方主要阶段，以场上1只效果怪兽为对象才能发动。从手卡选1只怪兽丢弃，作为对象的怪兽的效果直到回合结束时无效。 ②：恶魔族怪兽从手卡送去自己墓地的场合才能发动。从以下效果选1个直到回合结束时对这张卡适用。 ●不会被战斗破坏。 ●不会被对方的效果破坏。 ●不会成为对方的效果的对象。'),
(65623423, 'Gruesome Goo', '杀人污泥', 'キラー・ブロッブ', 'Normal Monster', 'Aqua', 'WATER', 3, 1300, 700, '史莱姆们的老大。尽管样子上没什么区别，但别小看它，否则可是会吃亏的哦。'),
(24215921, 'Gruesome Grave Squirmer', '地狱墓场蠕动者', 'ヘルグレイブ・スクワーマー', 'Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，自己场上有恶魔族怪兽存在的场合才能发动。这张卡从手卡特殊召唤。那之后，可以把自己场上1只「于贝尔」或者有那个卡名记述的怪兽破坏。 ②：把墓地的这张卡除外才能发动。从自己的手卡·墓地把「地狱墓场蠕动者」以外的1只攻击力和守备力是0的恶魔族怪兽特殊召唤。'),
(55608151, 'Gryphon Wing', '狮鹫之翼', 'グリフォンの翼', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方把「鹰身女妖的羽毛扫」发动时才能发动。那个效果无效，对方场上的魔法·陷阱卡全部破坏。'),
(34370473, 'Gryphon''s Feather Duster', '狮鹫的羽毛扫', 'グリフォンの羽根帚', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '破坏自己场上所有魔法·陷阱卡。自己回复被破坏的卡数量×500基本分。'),
(57346400, 'Guard Dog', '看门狗', 'ガード・ドッグ', 'Flip Effect Monster', 'Beast', 'EARTH', 3, 1500, 500, '反转：这个回合对方玩家不能特殊召唤。'),
(56198785, 'Guard Ghost', '背护卫', '背護衛', 'Effect Monster', 'Zombie', 'DARK', 4, 1800, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡从墓地的特殊召唤成功的场合，以自己场上1只怪兽为对象才能发动。这个回合，那只怪兽不会被战斗·效果破坏。 ②：这张卡被除外的回合的结束阶段才能发动。这张卡加入手卡。'),
(64283880, 'Guard Go!', '我怒隆共防！', 'ガードゴー！', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的「我我我」、「怒怒怒」、「隆隆隆」怪兽的其中任意种被战斗·效果破坏送去墓地的场合，以那1只怪兽为对象才能发动。那只怪兽特殊召唤。那之后，可以从手卡把「我我我」、「怒怒怒」、「隆隆隆」怪兽合计最多2只守备表示特殊召唤。'),
(53754104, 'Guard Mantis', '防御螳螂', 'ガード・マンティス', 'Effect Monster', 'Insect', 'WIND', 4, 1000, 2400, '这个卡名的①②的效果1回合各能使用1次。 ①：支付1000基本分才能发动。这张卡从手卡守备表示特殊召唤。只要这个效果特殊召唤的这张卡在怪兽区域表侧表示存在，自己不是昆虫族怪兽不能特殊召唤。 ②：对方回合，以自己场上1只昆虫族怪兽为对象才能发动。那只怪兽的表示形式变更。'),
(88928798, 'Guard Mines', '炸弹防御', 'ボム・ガード', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '持有「把自己场上存在的1只怪兽破坏的效果」的卡发动时才能发动。那个发动无效并破坏。并且再给与对方基本分500分伤害。'),
(48653261, 'Guard Penalty', '防守罚则', 'ガードペナルティ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择场上1只怪兽。这个回合选择的怪兽变成守备表示的场合，从自己卡组抽1张卡。'),
(99581584, 'Guard Penguin', '守卫企鹅', 'ガード・ペンギン', 'Effect Monster', 'Winged Beast', 'WATER', 4, NULL, 1200, '卡的效果让自己受到伤害时才能发动。这张卡从手卡特殊召唤，自己基本分回复受到的伤害的数值。'),
(17052477, 'Guarded Treasure', '守护神的宝札', '守護神の宝札', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：丢弃5张手卡才能把这张卡发动。自己从卡组抽2张。 ②：只要这张卡在魔法与陷阱区域存在，自己抽卡阶段的通常抽卡变成2张。'),
(68007326, 'Guardian Angel Joan', '守护天使 贞德', '守護天使 ジャンヌ', 'Effect Monster', 'Fairy', 'LIGHT', 7, 2800, 2000, '①：这张卡战斗破坏怪兽送去墓地的场合发动。自己基本分回复那只怪兽的原本攻击力的数值。'),
(73544866, 'Guardian Baou', '守护者·巴奥', 'ガーディアン・バオウ', 'Effect Monster', 'Fiend', 'DARK', 4, 800, 400, '当自己场上存在「破邪之大剑-黄昏」时才能召唤·反转召唤·特殊召唤。这张卡每战斗破坏对方1只怪兽并将其送去墓地，攻击力上升1000点。被这张卡战斗破坏的效果怪兽的效果无效化。'),
(10755153, 'Guardian Ceal', '守护者·希尔', 'ガーディアン・シール', 'Effect Monster', 'Pyro', 'FIRE', 4, 1700, 1400, '当自己场上存在「流星之弓-烨焰」时才能召唤·反转召唤·特殊召唤。将1张这张卡身上装备的自己的装备卡送去墓地，破坏对方场上1只怪兽。'),
(11321089, 'Guardian Chimera', '守护者・客迈拉', 'ガーディアン・キマイラ', 'Fusion Monster', 'Beast', 'DARK', 9, 3300, 3300, '卡名不同的怪兽×3 这张卡用只以手卡和自己场上的怪兽各1只以上为素材的融合召唤才能从额外卡组特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：这张卡用魔法卡的效果融合召唤的场合才能发动。自己抽出从手卡作为融合素材的数量，把从场上作为融合素材的数量的对方场上的卡破坏。 ②：只要自己墓地有「融合」存在，对方不能把这张卡作为效果的对象。'),
(18175965, 'Guardian Dreadscythe', '守护者·戴思塞斯', 'ガーディアン・デスサイス', 'Effect Monster', 'Fiend', 'DARK', 8, 2500, 2000, '这张卡不能通常召唤，用这张卡的效果才能特殊召唤。 ①：「守护者·艾托斯」被战斗·效果破坏送去自己墓地的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤成功时才能发动。从卡组把1张「死神的大镰-断魂」给这张卡装备。 ③：只要这张卡在怪兽区域存在，自己不能召唤·特殊召唤。 ④：这张卡从场上送去墓地的场合发动。把1张手卡送去墓地，这张卡从墓地特殊召唤。'),
(34022290, 'Guardian Eatos', '守护者・艾尔托斯', 'ガーディアン・エアトス', 'Effect Monster', 'Fairy', 'WIND', 8, 2500, 2000, '①：自己墓地没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：把这张卡装备的自己场上1张装备魔法卡送去墓地，以对方墓地最多3只怪兽为对象才能发动。那些怪兽除外。这张卡的攻击力直到回合结束时上升这个效果除外的怪兽数量×500。'),
(74367458, 'Guardian Elma', '守护者·艾尔玛', 'ガーディアン・エルマ', 'Effect Monster', 'Fairy', 'WIND', 3, 1300, 1200, '当自己场上存在「蝶之短剑-回音」时才能召唤·反转召唤·特殊召唤。这张卡召唤·特殊召唤成功时，可以从自己的墓地里选择1张装备魔法卡装备在这张卡身上。'),
(47150851, 'Guardian Grarl', '守护者·格拉尔', 'ガーディアン・グラール', 'Effect Monster', 'Dinosaur', 'EARTH', 5, 2500, 1000, '当自己场上存在「重力之斧-咆哮」时才能召唤·反转召唤·特殊召唤。当手卡仅有这张卡1张时，这张卡可以从手卡直接特殊召唤上场。'),
(9633505, 'Guardian Kay''est', '守护者·凯丝特', 'ガーディアン・ケースト', 'Effect Monster', 'Sea Serpent', 'WATER', 4, 1000, 1800, '当自己场上存在「静寂之杖-波纹」时才能召唤·反转召唤·特殊召唤。这张卡不受魔法效果影响。这张卡不能成为对方的攻击对象。'),
(33460840, 'Guardian of Felgrand', '巨龙之守护骑士', '巨竜の守護騎士', 'Effect Monster', 'Warrior', 'LIGHT', 4, 500, 500, '①：这张卡召唤·特殊召唤成功的场合才能发动。从自己的手卡·墓地选1只7·8星的龙族怪兽当作装备卡使用给这张卡装备。 ②：这张卡的攻击力·守备力上升这张卡的效果装备的怪兽的各自数值的一半。 ③：把自己场上1只怪兽和这张卡解放，以自己墓地1只7·8星的龙族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(71799173, 'Guardian of Order', '秩序守护者', 'ガーディアン・オブ・オーダー', 'Effect Monster', 'Warrior', 'LIGHT', 8, 2500, 1200, '自己场上有光属性怪兽表侧表示2只以上存在的场合，这张卡可以从手卡特殊召唤。「秩序守护者」在自己场上只能有1只表侧表示存在。'),
(67007102, 'Guardian of the Golden Land', '黄金乡守护者', '黄金郷のガーディアン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡发动后变成通常怪兽（不死族·光·8星·攻800/守2500）在怪兽区域特殊召唤。这张卡也当作陷阱卡使用。自己场上有「黄金卿 黄金国巫妖」存在的场合，可以再选场上1只表侧表示怪兽把攻击力变成0。 ②：自己·对方的结束阶段把墓地的这张卡除外才能发动。从卡组选1张「黄金国永生药」魔法·陷阱卡在自己场上盖放。'),
(89272878, 'Guardian of the Labyrinth', '冥界守门人', '冥界の番人', 'Normal Monster', 'Warrior', 'EARTH', 4, 1000, 1200, '守护着冥界入口的战士，对侵略者豪不留情的斩杀。'),
(47879985, 'Guardian of the Throne Room', '王室前的守护者', '王室前のガーディアン', 'Normal Monster', 'Machine', 'LIGHT', 4, 1650, 1600, '守护王室的机械士兵。穷追不舍地使用导弹进行攻击。'),
(61773610, 'Guardian of the Voiceless Voice', '肃声之守护者', '粛声のガーディアン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次，同一连锁上不能发动。 ①：仪式怪兽以外的自己场上的怪兽被战斗·效果破坏的场合才能发动。从手卡·卡组把1只「法理守护者」特殊召唤。 ②：把魔法与陷阱区域的表侧表示的这张卡送去墓地，以自己场上1只仪式怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升场上的其他怪兽的原本攻击力的合计数值。'),
(15771991, 'Guardian Slime', '守护者史莱姆', 'ガーディアン・スライム', 'Effect Monster', 'Aqua', 'WATER', 10, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己因战斗·效果受到伤害的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡和对方怪兽进行战斗的伤害计算时才能发动。这张卡的守备力只在那次伤害计算时上升那只对方怪兽的攻击力数值。 ③：这张卡从手卡·场上送去墓地的场合才能发动。从卡组把有「太阳神之翼神龙」的卡名记述的1张魔法·陷阱卡加入手卡。'),
(40659562, 'Guardian Sphinx', '守护者斯芬克斯', '守護者スフィンクス', 'Effect Monster', 'Rock', 'EARTH', 5, 1700, 2400, '这张卡1个回合可以有1次变回里侧守备表示。这张卡反转召唤成功时，对方场上的全部怪兽回到持有者手卡。'),
(75209824, 'Guardian Statue', '守护者雕像', 'ガーディアン・スタチュー', 'Effect Monster', 'Rock', 'EARTH', 4, 800, 1400, '这张卡1个回合1次可以变成里侧守备表示。这张卡反转召唤成功时，对方场上1只怪兽回到持有者的手卡。'),
(46037213, 'Guardian Tryce', '守护者·特莱斯', 'ガーディアン・トライス', 'Effect Monster', 'Thunder', 'LIGHT', 5, 1900, 1700, '当自己场上存在「闪光之双剑-雷震」时才能召唤·反转召唤·特殊召唤。这张卡被破坏送去墓地时，将墓地里存在的这张卡祭牲召唤时作为祭品的怪兽特殊召唤到自己场上。'),
(300302008, 'Guardians of the Tomb', NULL, NULL, 'Skill Card', 'Odion', NULL, NULL, NULL, NULL, NULL),
(59537380, 'Guardragon Agarpain', '守护龙 爱迦贝音', '守護竜アガーペイン', 'Link Monster', 'Dragon', 'DARK', NULL, 1500, NULL, '龙族怪兽2只 自己对「守护龙 阿迦佩因」1回合只能有1次特殊召唤，那个②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己不是龙族怪兽不能特殊召唤。 ②：自己主要阶段才能发动。从额外卡组把1只龙族怪兽往作为受2只以上的连接怪兽所连接区的，额外怪兽区域或者自己场上特殊召唤。'),
(6990577, 'Guardragon Andrake', '守护龙 安得擂克', '守護竜アンドレイク', 'Effect Monster', 'Dragon', 'WIND', 4, 2000, 600, '这张卡不能通常召唤，用卡的效果才能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡从手卡·卡组的特殊召唤成功的场合才能发动。这张卡的原本的攻击力·守备力直到下个回合的结束时变成2倍。 ②：这张卡从墓地的特殊召唤成功的场合或者除外的这张卡特殊召唤成功的场合，以对方场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(47393199, 'Guardragon Cataclysm', '崩界守护龙', '崩界の守護竜', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只龙族怪兽解放，以场上2张卡为对象才能发动。那些卡破坏。'),
(11908584, 'Guardragon Corewakening', '守护龙之核醒', '守護竜の核醒', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：从手卡把1只效果怪兽送去墓地才能发动。从自己的手卡·卡组·墓地选1只4星以下的龙族通常怪兽守备表示特殊召唤。'),
(86148577, 'Guardragon Elpy', '守护龙 希露比', '守護竜エルピィ', 'Link Monster', 'Dragon', 'DARK', NULL, 1000, NULL, '4星以下的龙族怪兽1只 自己对「守护龙 厄尔庇」1回合只能有1次特殊召唤，那个②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己不是龙族怪兽不能特殊召唤。 ②：自己主要阶段才能发动。从手卡·卡组把1只龙族怪兽往作为受2只以上的连接怪兽所连接区的自己场上特殊召唤。'),
(43411769, 'Guardragon Garmides', '守护龙 卡尔米德思', '守護竜ガルミデス', 'Effect Monster', 'Dragon', 'EARTH', 3, 1600, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：通常怪兽被送去自己墓地的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡在墓地存在的场合，从手卡把1只龙族怪兽送去墓地才能发动。这张卡加入手卡。'),
(11012154, 'Guardragon Justicia', '守护龙 尤司帝阿', '守護竜ユスティア', 'Normal Tuner Monster', 'Dragon', 'WATER', 2, NULL, 2100, '星键流下那不流的泪水，成就天命。神门崩鸣，蛇口吞下守护者的梦幻。其魂在初始之地，彼魂在终极之地。 ——这颗神狱之星将会在此开辟。'),
(13143275, 'Guardragon Pisty', '守护龙 必思缇', '守護竜ピスティ', 'Link Monster', 'Dragon', 'DARK', NULL, 1000, NULL, '4星以下的龙族怪兽1只 自己对「守护龙 毗斯缇」1回合只能有1次特殊召唤，那个②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己不是龙族怪兽不能特殊召唤。 ②：以自己的墓地·除外状态的1只龙族怪兽为对象才能发动。那只怪兽在作为受2只以上的连接怪兽所连接区的自己场上特殊召唤。'),
(79905468, 'Guardragon Promineses', '守护龙 普罗米奈喜思', '守護竜プロミネシス', 'Effect Monster', 'Dragon', 'FIRE', 1, 500, 200, '这个卡名的②的效果1回合只能使用1次。 ①：把手卡·场上的这张卡送去墓地，以自己场上1只龙族怪兽为对象才能发动。那只怪兽的攻击力·守备力直到对方回合结束时上升500。 ②：这张卡在墓地存在，通常怪兽被送去自己墓地的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(40003819, 'Guardragon Reincarnation', '转临之守护龙', '転臨の守護竜', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的场上·墓地把融合怪兽卡决定的融合素材怪兽除外，把那1只融合怪兽从额外卡组融合召唤。那个时候，融合素材怪兽必须全部是连接怪兽。'),
(50186558, 'Guardragon Shield', '守护龙之结界', '守護竜の結界', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：以自己场上1只龙族怪兽为对象才能发动。那只怪兽的攻击力·守备力直到对方回合结束时上升场上的连接怪兽的连接标记合计×100。 ②：1回合1次，只让自己场上的龙族怪兽1只被战斗·效果破坏的场合，可以作为代替从手卡·卡组把1只通常怪兽送去墓地。'),
(54629413, 'Guerilla Kite', '游击风筝', 'ゲリラカイト', 'Tuner Monster', 'Fiend', 'FIRE', 4, 1600, 200, '「游击风筝」的效果1回合只能使用1次。 ①：这张卡从场上送去墓地的场合发动。给与对方500伤害。'),
(98301564, 'Guiding Ariadne', '解放之阿里阿德涅', '解放のアリアドネ', 'Pendulum Effect Monster', 'Fairy', 'LIGHT', 4, 1700, 800, '①：这张卡被战斗·效果破坏的场合才能发动。从卡组把3张反击陷阱卡给对方观看，对方从那之中选1张。那1张卡加入自己手卡，剩余回到卡组。'),
(69865139, 'Guiding Light', '天轮之葬送士', '天輪の葬送士', 'Effect Monster', 'Fairy', 'LIGHT', 1, NULL, NULL, '①：这张卡召唤成功时，以自己墓地1只光属性·1星怪兽为对象才能发动。那只光属性怪兽特殊召唤。'),
(45883110, 'Guiding Quem, the Virtuous', '引导之圣女 库妸㽗', '導きの聖女クエム', 'Tuner Monster', 'Spellcaster', 'LIGHT', 4, 1500, 1500, '这个卡名在规则上也当作「教导」卡、「死狱乡」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。把1只「阿不思的落胤」或者1张有那个卡名记述的卡从卡组送去墓地。 ②：自己·对方的卡从额外卡组离开的场合，以除「引导的圣女 奎姆」外的自己墓地1只「阿不思的落胤」或者有那个卡名记述的怪兽为对象才能发动。那只怪兽特殊召唤。'),
(88695895, 'Guilt of the Sinful Spoils', '罪宝的咎人', '罪宝の咎人', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「迪亚贝尔斯塔尔」怪兽卡存在，对方从卡组·额外卡组把怪兽特殊召唤的场合，以对方场上1只怪兽为对象才能发动。那只怪兽回到卡组。 ②：自己的「迪亚贝尔斯塔尔」怪兽和对方怪兽进行战斗的从伤害步骤开始时到伤害计算前，把墓地的这张卡除外才能发动。那只对方怪兽的攻击力直到回合结束时变成一半。'),
(61822419, 'Guilt-Gripping Morganite', '拥抱罪咎的绿柱魔瞳', '咎を擁く魔瞳', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：这次决斗中，以下效果各适用。 ●自己不能把手卡的怪兽的效果发动。 ●自己在5星以上的怪兽召唤的场合需要的解放可以不用。 ●自己要为魔法·陷阱卡发动而支付的基本分变成不需要。 ②：把墓地的这张卡除外，把手卡1张「魔瞳」卡给对方观看才能发动。给人观看的卡回到卡组最下面。那之后，自己抽1张。'),
(79724755, 'Guitar Gurnards Duonigis', '黄纺鮄 黄鲂二重奏', '黄紡鮄デュオニギス', 'Effect Monster', 'Sea Serpent', 'WATER', 3, 1500, 700, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。把自己场上的水属性怪兽数量的卡从对方卡组上面除外。 ②：以自己场上1只4星以下的水属性怪兽为对象才能发动。那只怪兽的等级上升那个原本等级数值。 ③：把墓地的这张卡除外才能发动。选场上1只水属性怪兽，那个攻击力直到回合结束时上升除外中的怪兽数量×100。'),
(41788781, 'Guldfaxe of the Nordic Beasts', '极星兽 古尔法克西', '極星獣グルファクシ', 'Tuner Monster', 'Beast', 'LIGHT', 4, 1600, 1000, '对方场上有同调怪兽表侧表示存在，自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。'),
(90207654, 'Gullveig of the Nordic Ascendant', '极星天 古尔薇格', '極星天グルヴェイグ', 'Link Monster', 'Fairy', 'LIGHT', NULL, 800, NULL, '5星以下的「极星」怪兽1只 这个卡名的①的效果1回合只能使用1次。 ①：这张卡连接召唤成功的场合才能发动。选自己的手卡·场上最多3张卡除外，把那个数量的「极星」怪兽从卡组守备表示特殊召唤。这个效果发动过的回合，自己不能通常召唤，不是「极神」怪兽不能特殊召唤。 ②：只要这张卡所连接区有「极神」怪兽存在，对方不能把那只怪兽作为效果的对象，不能选择这张卡作为攻击对象。'),
(38975369, 'Gundari', '军荼利', '軍荼利', 'Spirit Monster', 'Pyro', 'FIRE', 4, 1000, 200, '这张卡不能特殊召唤。召唤·反转的回合的结束阶段时回到持有者手卡。这张卡和同调怪兽进行战斗的场合，不进行伤害计算，那只怪兽和这张卡回到持有者手卡。'),
(4079728, 'Gung-Ho! Springans!', '共好！守宝团！', 'ガンホー！スプリガンズ！', 'XYZ Monster', 'Machine', 'FIRE', 4, 2500, 1600, '4星「护宝炮妖」怪兽×2只以上 这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡超量召唤的场合或者被送去墓地的场合才能发动。从自己的卡组·墓地把1只「护宝炮妖船长 尾宿五」特殊召唤。 ②：把这张卡2个超量素材取除才能发动。从卡组选以下怪兽之内1只加入手卡或特殊召唤。 ●「护宝炮妖」怪兽 ●「兽带斗神」怪兽 ●「阿不思的落胤」或者有那个卡名记述的怪兽'),
(65749035, 'Gungnir, Dragon of the Ice Barrier', '冰结界之龙 天枪龙', '氷結界の龍 グングニール', 'Synchro Monster', 'Dragon', 'WATER', 7, 2500, 1700, '调整＋调整以外的水属性怪兽1只以上 ①：1回合1次，把最多2张手卡丢弃去墓地，以丢弃数量的对方场上的卡为对象才能发动。那些卡破坏。'),
(83008724, 'Gunkan Suship Catch-of-the-Day', '军贯推荐捏', 'おすすめ軍貫握り', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，把手卡1只「舍利军贯」给对方观看才能发动。给这张卡放置1个指示物，额外卡组1只「军贯」超量怪兽给对方观看，对方宣言1个在「军贯」超量怪兽有卡名记述的除「舍利军贯」以外的「军贯」怪兽的卡名。自己把对方宣言的卡从卡组加入手卡。不能加入的场合，这张卡回到持有者卡组。 ②：这张卡被对方破坏的场合发动。对方支付这张卡放置的指示物数量×500基本分。'),
(24393683, 'Gunkan Suship Daily Special', '军贯随性捏', 'きまぐれ軍貫握り', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡也能把手卡1只「舍利军贯」给对方观看来发动。 ①：从卡组把3只「军贯」怪兽给对方观看，对方从那之中选1只。那1只怪兽加入自己手卡，剩余回到卡组。把「舍利军贯」给人观看发动的场合，加入手卡的怪兽由自己来选。 ②：把墓地的这张卡除外，以自己墓地3只「军贯」怪兽为对象才能发动。那些怪兽加入卡组。那之后，自己从卡组抽1张。这个效果在这张卡送去墓地的回合不能发动。'),
(61027400, 'Gunkan Suship Ikura', '鲑鱼子军贯', 'いくらの軍貫', 'Effect Monster', 'Aqua', 'FIRE', 4, 200, 300, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有「舍利军贯」存在的场合，这张卡可以从手卡特殊召唤。 ②：自己主要阶段才能发动。从自己卡组上面把3张卡翻开。可以从那之中选1只「舍利军贯」加入手卡或特殊召唤。剩下的卡回到卡组。'),
(75215744, 'Gunkan Suship Ikura-class Dreadnought', '弩级军贯－鲑鱼子型一号舰', '弩級軍貫－いくら型一番艦', 'XYZ Monster', 'Aqua', 'FIRE', 4, 2200, 300, '4星怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：这张卡超量召唤成功的场合才能发动。那些作为超量召唤的素材的怪兽的以下效果适用。 ●「舍利军贯」：自己从卡组抽1张。 ●「鲑鱼子军贯」：这张卡在同1次的战斗阶段中可以作2次攻击。 ②：1回合1次，从额外卡组特殊召唤的自己的「军贯」怪兽给与对方战斗伤害时，以对方场上1张卡为对象才能发动。那张卡破坏。'),
(24639891, 'Gunkan Suship Shari', '舍利军贯', 'しゃりの軍貫', 'Normal Monster', 'Aqua', 'FIRE', 4, 2000, NULL, '走进从以前就开始在意的一家专注于军贯的军港。这里的舍利饭每年仅制造两千艘，且其独自开发的黏性小的旧米能让人享受到一种其他港没有的厚重感，因此是许多行家都赞不绝口的绝品。港内氛围也是格调高雅，令人心潮澎湃。 期盼已久的军贯不论醋的比例、捏的力道、造型都堪称职人技艺，可谓名不虚传。店主说「江户前线(EDO－FRONT)生产的醇厚柔和而带醇香的赤醋也预定于近日入港」，让人非常期待其调和。 周边海域有些许嘈杂这一点真的挺可惜的……。也包含了对今后的期待，这次请允许我给4颗星！'),
(63748694, 'Gunkan Suship Shari Red', '赤舍利军贯', '赤しゃりの軍貫', 'Effect Monster', 'Aqua', 'FIRE', 4, NULL, 2000, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡的卡名只要在手卡·卡组·场上·墓地存在当作「舍利军贯」使用。 ②：把手卡1只其他的「舍利军贯」给对方观看才能发动。这张卡从手卡特殊召唤。那之后，以下可以适用。 ●「舍利军贯」以外的1只「军贯」怪兽效果无效从卡组特殊召唤，用那只怪兽和这张卡为素材，把有那只怪兽的卡名记述的1只超量怪兽当作超量召唤从额外卡组特殊召唤。'),
(78362751, 'Gunkan Suship Shirauo', '白鱼军贯', 'しらうおの軍貫', 'Effect Monster', 'Aqua', 'FIRE', 4, 200, 250, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有着「舍利军贯」或者有「舍利军贯」在作为超量素材中的超量怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己主要阶段才能发动。从手卡把「银鱼军贯」以外的1只「军贯」怪兽特殊召唤。那之后，可以从自己的卡组·墓地选「舍利军贯」任意数量用喜欢的顺序在卡组最上面放置。'),
(21293424, 'Gunkan Suship Shirauo-class Carrier', '航母军贯－白鱼型特务舰', '空母軍貫－しらうお型特務艦', 'XYZ Monster', 'Aqua', 'FIRE', 4, 2200, 250, '4星怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：这张卡超量召唤成功的场合才能发动。那些作为超量召唤的素材的怪兽的以下效果适用。 ●「舍利军贯」：自己从卡组抽1张。 ●「银鱼军贯」：从卡组把1张「军贯」魔法·陷阱卡加入手卡。 ②：只要场地区域有表侧表示卡存在，从额外卡组特殊召唤的自己的「军贯」怪兽不会被对方的效果破坏，攻击力上升那原本守备力数值。'),
(42377643, 'Gunkan Suship Uni', '海胆军贯', 'うにの軍貫', 'Effect Monster', 'Aqua', 'FIRE', 5, 900, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡以外的手卡1张「军贯」卡给对方观看才能发动。这张卡从手卡特殊召唤。那之后，给人观看的卡的以下效果适用。 ●「舍利军贯」：可以把给人观看的怪兽特殊召唤。 ●那以外：给人观看的卡回到卡组最下面。 ②：以自己场上1只「军贯」怪兽为对象才能发动。那只怪兽的等级变成4星或者5星。那之后，可以从卡组把1只「舍利军贯」加入手卡。'),
(94798725, 'Gunkan Suship Uni-class Super-Dreadnought', '超弩级军贯－海胆型二号舰', '超弩級軍貫－うに型二番艦', 'XYZ Monster', 'Aqua', 'FIRE', 5, 2900, 500, '5星怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：这张卡超量召唤成功的场合才能发动。那些作为超量召唤的素材的怪兽的以下效果适用。 ●「舍利军贯」：自己从卡组抽1张。 ●「海胆军贯」：这张卡可以直接攻击。 ②：自己主要阶段以及对方战斗阶段1次，以最多有从额外卡组特殊召唤的自己的「军贯」怪兽数量的对方场上的表侧表示的卡为对象才能发动。那些卡的效果无效。'),
(62200831, 'Gunkan Sushipyard Seaside Supper Spot', '军贯处“海栈”', '軍貫処 『海せん』', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：1回合1次，自己对「军贯」怪兽的召唤·特殊召唤成功的场合才能发动（伤害步骤也能发动）。从卡组选1张「军贯」卡在卡组最上面放置。 ②：1回合1次，从额外卡组特殊召唤的自己场上的「军贯」怪兽被对方送去墓地的场合发动。对方支付那个守备力数值的基本分。那之后，自己可以让以下效果适用。 ●手卡1只「舍利军贯」特殊召唤，把1只「军贯」超量怪兽在那上面重叠当作超量召唤从额外卡组特殊召唤。'),
(2405631, 'Guoglim, Spear of the Ghoti', '游魊之死棘 果格里姆', 'ゴーティスの死棘グオグリム', 'Synchro Monster', 'Fish', 'WATER', 8, 2700, NULL, '鱼族调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡和对方怪兽进行战斗的伤害步骤开始时才能发动。那只对方怪兽除外。 ②：对方准备阶段才能发动。这张卡除外。那之后，若作为这张卡的同调召唤的素材用过的一组怪兽在自己墓地齐集，可以把那一组特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合除外。'),
(55762976, 'Gussari @Ignister', '利刃刺刺＠伊格尼斯者', 'グッサリ＠イグニスター', 'Effect Monster', 'Cyberse', 'EARTH', 8, 3000, 3000, '这个卡名的①②③的效果1回合各能使用1次。 ①：连接怪兽被战斗破坏时才能发动。这张卡从手卡特殊召唤。 ②：自己的连接怪兽战斗破坏对方怪兽时才能发动。给与对方那只对方怪兽的原本攻击力数值的伤害。 ③：自己的连接怪兽和对方怪兽进行战斗的攻击宣言时，把墓地的这张卡除外才能发动。那些双方怪兽的攻击力变成3000。'),
(73079365, 'Gust', '突风', '突風', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方的卡的效果让自己场上的魔法卡被破坏送去墓地时才能发动。选择场上1张魔法·陷阱卡破坏。'),
(55321970, 'Gust Fan', '突风之扇', '突風の扇', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '风属性的怪兽才能装备。装备的怪兽攻击力上升400，守备力下降200。'),
(9897998, 'Gusto Codor', '薰风鹫', 'ガスタ・コドル', 'Effect Monster', 'Winged Beast', 'WIND', 3, 1000, 400, '这张卡战斗破坏对方怪兽送去墓地时，可以从自己卡组把1只守备力1500以下的念动力族·风属性怪兽特殊召唤。'),
(91662792, 'Gusto Egul', '薰风鹰', 'ガスタ・イグル', 'Tuner Monster', 'Winged Beast', 'WIND', 1, 200, 400, '这张卡被战斗破坏送去墓地时，可以从自己卡组把1只调整以外的4星以下的名字带有「薰风」的怪兽特殊召唤。'),
(46044841, 'Gusto Falco', '薰风隼', 'ガスタ・ファルコ', 'Tuner Monster', 'Winged Beast', 'WIND', 2, 600, 1400, '场上表侧表示存在的这张卡被战斗以外送去墓地时，可以从自己卡组把1只名字带有「薰风」的怪兽里侧守备表示特殊召唤。'),
(42082363, 'Gusto Griffin', '薰风狮鹫', 'ガスタ・グリフ', 'Effect Monster', 'Winged Beast', 'WIND', 2, 800, 300, '这张卡从手卡送去墓地的场合，可以从自己卡组把1只名字带有「薰风」的怪兽特殊召唤。「薰风狮鹫」的效果1回合只能使用1次。'),
(65277087, 'Gusto Gulldo', '薰风鹏', 'ガスタ・ガルド', 'Tuner Monster', 'Winged Beast', 'WIND', 3, 500, 500, '这张卡从场上送去墓地时，可以从自己卡组把1只2星以下的名字带有「薰风」的怪兽特殊召唤。'),
(336369, 'Gusto Squirro', '薰风松鼠', 'ガスタ・スクイレル', 'Tuner Monster', 'Thunder', 'WIND', 2, NULL, 1800, '这张卡被卡的效果破坏送去墓地时，可以从自己卡组把1只5星以上的名字带有「薰风」的怪兽特殊召唤。'),
(28066831, 'Gusto Thunbolt', '薰风雷狼', 'ガスタ・サンボルト', 'Effect Monster', 'Thunder', 'WIND', 4, 1500, 1200, '这张卡被战斗破坏送去墓地的场合，那次战斗阶段结束时可以把自己墓地存在的1只名字带有「薰风」的怪兽从游戏中除外，从自己卡组把1只守备力1500以下的念动力族·风属性怪兽特殊召唤。'),
(86277379, 'Gusto Vedir', '薰风苍鹰', 'ガスタ・ヴェズル', 'Tuner Monster', 'Winged Beast', 'WIND', 3, 600, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在，场上的表侧表示的「薰风」怪兽被战斗破坏的场合或者被送去自己墓地的场合才能发动。这张卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1只「薰风」怪兽送去墓地。那之后，可以从手卡把1只「薰风」怪兽特殊召唤。'),
(33970665, 'Guts of Steel', '废钢铁的意志', 'ポンコツの意地', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择在自己墓地存在的3只名字带有「废铁」的怪兽发动。对方选择那些中的1只。那只怪兽在自己或对方场上特殊召唤，其余的卡从游戏中除外。'),
(19748583, 'Gwenhwyfar, Queen of Noble Arms', '怀抱圣剑的王后 桂妮薇儿', '聖剣を抱く王妃ギネヴィア', 'Effect Monster', 'Spellcaster', 'LIGHT', 2, 300, 300, '「怀抱圣剑的王后 桂妮薇儿」的①的效果1回合只能使用1次。 ①：以自己场上1只「圣骑士」怪兽为对象才能发动。手卡·墓地的这张卡当作攻击力上升300的装备卡使用给那只自己怪兽装备。 ②：得到装备怪兽的属性的以下效果。 ●光：装备怪兽被效果破坏的场合，可以作为代替把这张卡破坏。 ●暗：装备怪兽和对方怪兽进行战斗的伤害步骤开始时才能发动。那只怪兽破坏。那之后这张卡破坏。'),
(9817927, 'Gyaku-Gire Panda', '反怒的熊猫', '逆ギレパンダ', 'Effect Monster', 'Beast', 'EARTH', 3, 800, 1600, '对方场上每存在1只怪兽，这张卡的攻击力上升500点。这张卡攻击守备表示的怪兽时，若攻击力超过那个守备力，给与对方那个数值的战斗伤害。'),
(31122090, 'Gyakutenno Megami', '逆转女神', '逆転の女神', 'Normal Monster', 'Fairy', 'LIGHT', 6, 1800, 2000, '用神圣之力守护弱者，给予逆转之力的女神。'),
(18325492, 'Gyroid', '旋翼机人', 'ジャイロイド', 'Effect Monster', 'Machine', 'WIND', 3, 1000, 1000, '这张卡1回合1次不会被战斗破坏。（伤害计算适用）。'),
(74825788, 'H - Heated Heart', 'H－炽热之心', 'H－ヒートハート', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升500，这个回合那只怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(18482473, 'H-E-R-O Flash!', NULL, NULL, 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(18377261, 'Ha-Re the Sword Mikanko', '剑之御巫 波礼', '剣の御巫ハレ', 'Effect Monster', 'Warrior', 'FIRE', 3, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡没有装备卡装备的场合，这张卡的战斗发生的对自己的战斗伤害变成0，有装备的场合，这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害由对方代受。 ②：这张卡有装备卡被装备的场合才能发动。从卡组把1张「御巫」装备魔法卡加入手卡。'),
(97466712, 'Hack Worm', '入侵蠕虫', 'ハック・ワーム', 'Effect Monster', 'Machine', 'DARK', 1, 400, NULL, '①：对方场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。'),
(28357177, 'Hade-Hane', '华丽哈尼', '派手ハネ', 'Flip Effect Monster', 'Beast', 'EARTH', 5, 900, 1000, '反转：可以选择场上最多3只怪兽回到手卡。'),
(9763474, 'Haggard Lizardose', '盛悴剧毒蜥', '盛悴のリザルドーズ', 'Link Monster', 'Reptile', 'WATER', NULL, 800, NULL, '卡名不同的怪兽2只 这个卡名的效果1回合只能使用1次。 ①：从自己的场上（表侧表示）·墓地把1只攻击力2000以下的怪兽除外，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时变成和为这个效果发动而除外的怪兽的原本攻击力相同。把原本种族是爬虫类族的怪兽除外发动的场合，再让自己抽1张。'),
(34137269, 'Hailon, the Timelord', '时械神 海隆', '時械神ハイロン', 'Effect Monster', 'Fairy', 'EARTH', 10, NULL, NULL, '这张卡不能从卡组特殊召唤。 ①：自己场上没有怪兽存在的场合，这张卡可以不用解放作召唤。 ②：这张卡不会被战斗·效果破坏，这张卡的战斗发生的对自己的战斗伤害变成0。 ③：这张卡进行战斗的战斗阶段结束时发动。自己基本分比对方少的场合，给与对方那个相差数值的伤害。 ④：自己准备阶段发动。这张卡回到持有者卡组。'),
(41729254, 'Hajun, the Winged Mayakashi', '翼之魔妖－波旬', '翼の魔妖－波旬', 'Effect Monster', 'Zombie', 'WIND', 1, 600, 400, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「翼之魔妖-波旬」以外的1只「魔妖」怪兽特殊召唤。 ②：只要这张卡在怪兽区域存在，自己不是「魔妖」怪兽不能从额外卡组特殊召唤。'),
(6799227, 'Half Counter', '半反击', 'ハーフ・カウンター', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的怪兽被攻击的场合，那次伤害计算时才能发动。成为攻击对象的1只自己怪兽的攻击力直到结束阶段时上升攻击怪兽的原本攻击力一半的数值。'),
(15552258, 'Half or Nothing', '一半或停止', 'ハーフorストップ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方回合的战斗阶段时才能发动。对方从以下效果选择1个适用。 ●直到战斗阶段结束时，自己场上存在的全部怪兽的攻击力变成一半数值。 ●把战斗阶段结束。'),
(73048641, 'Half Shut', '半封', 'ハーフ・シャット', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以场上1只表侧表示怪兽为对象才能发动。那只怪兽直到回合结束时攻击力变成一半，不会被战斗破坏。'),
(981540, 'Half Unbreak', '半伤不破', 'ハーフ・アンブレイク', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择场上1只怪兽才能发动。这个回合，选择的怪兽不会被战斗破坏，那只怪兽的战斗发生的对自己的战斗伤害变成一半。'),
(20285786, 'Halfway to Forever', '杰作碎片', 'マスター・ピース', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地2只怪兽为对象才能发动。那2只怪兽效果无效特殊召唤，只用那2只为素材把1只光属性「霍普」超量怪兽超量召唤。'),
(4341721, 'Hallo-Ween!', '不给糖就捣蛋！', 'Trick or Treat！', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己的卡组·墓地把1只「淘气大精灵 哈洛」或「点心大精灵 维恩」加入手卡。'),
(54611591, 'Hallo, the Spirit of Tricks', '淘气大精灵 哈洛', 'イタズラの大精霊ハロ', 'Effect Monster', 'Fiend', 'DARK', 4, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。这张卡在自己场上表侧表示存在的场合，对方从以下效果选1个，自己让那个效果适用。 ●这张卡的攻击力上升自己墓地的恶魔族怪兽数量×800。 ●给与对方为自己墓地的恶魔族怪兽数量×500伤害。 ②：这张卡被战斗·效果破坏的场合才能发动。对方场上1只怪兽送去墓地。'),
(77994337, 'Hallohallo', '万圣哈喽', 'ハロハロ', 'Pendulum Tuner Effect Monster', 'Fiend', 'DARK', 3, 800, 600, '万万圣爱甜甜糖。 找糖糖，这逛逛，那瞧瞧。 不给糖果就捣蛋，招招耍你团团转。  心慌慌已来不及。 花样万变请期待。'),
(88789641, 'Hallowed Life Barrier', '神圣生命防护罩', 'ホーリーライフバリアー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '丢弃1张手卡。这张卡发动的回合，对方造成的伤害全部为0。'),
(80811661, 'Hamburger Recipe', '汉堡的食谱', 'ハンバーガーのレシピ', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「饥饿的汉堡」的降临必需。 ①：从自己的手卡·场上把等级合计直到6以上的怪兽解放，从手卡把「饥饿的汉堡」仪式召唤。'),
(44790889, 'Hammer Bounzer', '重锤突击保镖', 'ハンマーラッシュ・バウンサー', 'Effect Monster', 'Warrior', 'EARTH', 6, 2300, 2000, '对方场上有卡存在，自己场上没有卡存在的场合，这张卡可以不用解放作召唤。自己场上没有魔法·陷阱卡存在，这张卡向对方怪兽攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。'),
(17201174, 'Hammer Shark', '锤鲨', 'ハンマー・シャーク', 'Effect Monster', 'Fish', 'WATER', 4, 1700, 1500, '1回合1次，自己的主要阶段时才能发动。这张卡的等级下降1星，从手卡把1只水属性·3星以下的怪兽特殊召唤。'),
(26412047, 'Hammer Shot', '槌击', 'ハンマーシュート', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上的攻击表示怪兽之内攻击力最高的1只怪兽破坏。'),
(32491822, 'Hamon, Lord of Striking Thunder', '降雷皇哈蒙', '降雷皇ハモン', 'Effect Monster', 'Thunder', 'LIGHT', 10, 4000, 4000, '这张卡不能通常召唤。把自己场上3张表侧表示的永续魔法卡送去墓地的场合才能特殊召唤。 ①：只要这张卡在怪兽区域守备表示存在，对方怪兽不能选择这张卡以外的怪兽作为攻击对象。 ②：这张卡战斗破坏对方怪兽送去墓地的场合发动。给与对方1000伤害。'),
(53270092, 'Han-Shi Kyudo Spirit', '弓道魂 范士', 'キュウドウ魂 HAN－SHI', 'Spirit Monster', 'Warrior', 'WIND', 5, 2400, 1000, '①：这张卡召唤成功时才能发动。和自己的灵摆区域的卡相同纵列的自己的卡全部回到持有者手卡。那之后，可以从卡组把「弓道魂 范士」以外的1只攻击力2400/守备力1000的怪兽加入手卡。 ②：这张卡召唤·反转的回合的结束阶段发动。这张卡回到持有者手卡。'),
(74519184, 'Hand Destruction', '手牌断杀', '手札断殺', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：双方玩家把2张手卡送去墓地。那之后，各自从卡组抽2张。'),
(98446407, 'Hand of Nephthys', '奈芙蒂斯的引导者', 'ネフティスの導き手', 'Effect Monster', 'Spellcaster', 'WIND', 2, 600, 600, '①：把自己场上1只怪兽和这张卡解放才能发动。从手卡·卡组把1只「奈芙提斯之凤凰神」特殊召唤。'),
(78792195, 'Hand of the Six Samurai', '六武众的先导', '六武衆の露払い', 'Effect Monster', 'Warrior', 'FIRE', 3, 1600, 1000, '自己场上有这张卡以外的名字带有「六武众」的怪兽表侧表示存在的场合才能发动。可以把自己场上存在的1只名字带有「六武众」的怪兽解放，场上存在的1只怪兽破坏。'),
(94535485, 'Hand-Holding Genie', '携手魔人', '手をつなぐ魔人', 'Effect Monster', 'Fiend', 'DARK', 4, 1000, 1600, '①：只要这张卡在怪兽区域存在，对方不能选择其他怪兽作为攻击对象。 ②：这张卡的守备力上升这张卡以外的自己场上的表侧守备表示怪兽的原本守备力的合计数值。'),
(97904474, 'Handcuffs Dragon', '手铐龙', '手錠龍', 'Effect Monster', 'Dragon', 'WIND', 5, 1800, 1800, '这张卡被对方怪兽的攻击破坏送去墓地时，可以把这张卡当作装备卡使用给那只怪兽装备。装备怪兽的攻击力下降1800。装备怪兽被破坏让这张卡送去墓地时，这张卡可以在自己场上特殊召唤。'),
(97637162, 'Handigallop', '让步小快马', 'ハンディ・ギャロップ', 'Effect Monster', 'Beast', 'EARTH', 1, NULL, NULL, '①：这张卡不能直接攻击。 ②：这张卡的攻击力上升双方基本分差的数值。 ③：自己基本分比对方多的场合，这张卡的攻击发生的对对方的战斗伤害由自己代受。'),
(7089711, 'Hane-Hane', '哈尼哈尼', 'ハネハネ', 'Flip Effect Monster', 'Beast', 'EARTH', 2, 450, 500, '①：这张卡反转的场合，以场上1只怪兽为对象发动。那只怪兽回到持有者手卡。'),
(20450925, 'Hanewata', '羽翼棉花', 'ハネワタ', 'Tuner Monster', 'Fairy', 'LIGHT', 1, 200, 300, '①：把这张卡从手卡丢弃才能发动。这个回合，自己受到的效果伤害变成0。这个效果在对方回合也能发动。'),
(84285623, 'Haniwa', '埴轮', 'はにわ', 'Normal Monster', 'Rock', 'EARTH', 2, 500, 500, '古代王墓中守护宝物的土人偶。'),
(5640330, 'Hannibal Necromancer', '汉尼拔死灵师', 'ハンニバル・ネクロマンサー', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1400, 1800, '①：这张卡召唤成功的场合发动。给这张卡放置1个魔力指示物（最多1个）。 ②：把这张卡1个魔力指示物取除，以场上1张表侧表示的陷阱卡为对象才能发动。那张表侧表示的陷阱卡破坏。'),
(47330808, 'Hapi, Guidance of Horus', '荷鲁斯的先导－哈庇', 'ホルスの先導－ハーピ', 'Effect Monster', 'Beast-Warrior', 'WIND', 8, 2400, 1600, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有「王之棺」存在的场合，这张卡可以从墓地特殊召唤。 ②：这张卡在怪兽区域存在的状态，自己场上的其他卡因对方的效果从场上离开的场合，以自己·对方的墓地·除外状态的卡合计2张为对象才能发动。那2张卡加入持有者手卡或那2张卡回到卡组。'),
(99030164, 'Happy Lover', '幸福恋使', 'ハッピー・ラヴァー', 'Normal Monster', 'Fairy', 'LIGHT', 2, 800, 500, '从头上放出心形的光给予恋人以幸福的小天使。'),
(20060230, 'Hard Armor', '坚硬铠甲', 'ハードアーマー', 'Normal Monster', 'Warrior', 'EARTH', 3, 300, 1200, '拥有心灵的铠甲，坚硬的身体装备在战士身上。'),
(68875140, 'Hard-sellin'' Goblin', '哥布林推销员', '押し売りゴブリン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '每次自己场上的怪兽给与对方玩家战斗伤害，对方的魔法与陷阱卡区域存在的1张卡回到持有者手卡。'),
(94374859, 'Hard-sellin'' Zombie', '僵尸推销员', '押し売りゾンビ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '每次自己场上的怪兽给与对方玩家战斗伤害，选择对方墓地存在的1张卡回到对方卡组最下面。'),
(68473226, 'Hardened Armed Dragon', '坚甲战龙', 'ハードアームドラゴン', 'Effect Monster', 'Dragon', 'EARTH', 4, 1500, 800, '①：这张卡可以把手卡1只8星以上的怪兽送去墓地，从手卡特殊召唤。 ②：把这张卡解放作召唤的7星以上的怪兽不会被效果破坏。'),
(31531170, 'Harmonic Oscillation', '共鸣的振动', '共鳴する振動', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方的灵摆区域有2张卡存在的场合，以那2张卡为对象才能发动。那2张卡在对方的灵摆区域存在，这个回合自己灵摆召唤的场合，可以用对方一组灵摆刻度来灵摆召唤。那个场合，不是从额外卡组中不能把怪兽灵摆召唤。'),
(7473735, 'Harmonic Synchro Fusion', '异界共鸣－同步结合', '異界共鳴－シンクロ・フュージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不是融合·同调怪兽不能从额外卡组特殊召唤。 ①：把自己场上的表侧表示的调整和调整以外的怪兽各1只送去墓地才能发动。以下怪兽各1只从额外卡组特殊召唤。 ●墓地的那2只怪兽为素材可以同调召唤的同调怪兽 ●墓地的那2只怪兽为素材可以融合召唤的融合怪兽'),
(58441120, 'Harmonic Waves', '波动共鸣', '波動共鳴', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择场上表侧表示存在的1只怪兽发动。选择的怪兽的等级直到结束阶段时变成4星。'),
(73941492, 'Harmonizing Magician', '调弦的魔术师', '調弦の魔術師', 'Pendulum Tuner Effect Monster', 'Spellcaster', 'DARK', 4, NULL, NULL, '这张卡不能从额外卡组特殊召唤，把这张卡作为融合·同调·超量召唤的素材的场合，其他素材必须全部是「魔术师」灵摆怪兽。这个卡名的怪兽效果1回合只能使用1次。 ①：这张卡从手卡灵摆召唤时才能发动。从卡组把「调弦之魔术师」以外的1只「魔术师」灵摆怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化，从场上离开的场合除外。'),
(90238142, 'Harpie Channeler', '神鹰通灵者', 'ハーピィ・チャネラー', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1400, 1300, '这个卡名的③的效果1回合只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「鹰身女郎」使用。 ②：只要自己场上有龙族怪兽存在，这张卡的等级变成7星。 ③：从手卡丢弃1张「鹰身」卡才能发动。从卡组把「鹰身通灵师」以外的1只「鹰身」怪兽守备表示特殊召唤。'),
(85696777, 'Harpie Conductor', '神鹰指挥者', 'ハーピィ・コンダクター', 'Link Monster', 'Winged Beast', 'WIND', NULL, 1900, NULL, '风属性怪兽2只 这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「鹰身女郎」使用。 ②：自己场上的「鹰身」怪兽被战斗·效果破坏的场合，可以作为代替把自己场上1张魔法·陷阱卡破坏。 ③：自己场上的其他的表侧表示的「鹰身」怪兽回到自己手卡的场合，以对方场上1只特殊召唤的怪兽为对象才能发动。那只怪兽回到手卡。'),
(68815132, 'Harpie Dancer', '神鹰舞者', 'ハーピィ・ダンサー', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1200, 1000, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「鹰身女郎」使用。 ②：以自己场上1只风属性怪兽为对象才能发动。那只怪兽回到持有者手卡。那之后，可以把1只风属性怪兽召唤。'),
(34100324, 'Harpie Girl', '鹰身少女', 'ハーピィ・ガール', 'Normal Monster', 'Winged Beast', 'WIND', 2, 500, 500, '梦想有一天能以美丽的姿态华丽飞舞、敏锐攻击的鹰身少女。'),
(56585883, 'Harpie Harpist', '神鹰竖琴奏者', 'ハーピィ・ハーピスト', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1700, 600, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「鹰身女郎」使用。 ②：这张卡召唤时，以自己场上1只其他的鸟兽族怪兽和对方场上1只表侧表示怪兽为对象才能发动。那些怪兽回到手卡。 ③：这张卡被送去墓地的回合的结束阶段才能发动。从卡组把1只攻击力1500以下的鸟兽族·4星怪兽加入手卡。'),
(76812113, 'Harpie Lady', '神鹰女郎', 'ハーピィ・レディ', 'Normal Monster', 'Winged Beast', 'WIND', 4, 1300, 1400, '人长出羽毛的魔兽，表演华丽的舞蹈进行快攻。'),
(91932350, 'Harpie Lady 1', '鹰身女郎1', 'ハーピィ・レディ１', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1300, 1400, '这张卡的卡名当作「鹰身女郎」使用。只要这张卡在场上存在，场上的风属性怪兽攻击力上升300。'),
(27927359, 'Harpie Lady 2', '鹰身女郎2', 'ハーピィ・レディ２', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1300, 1400, '这张卡的卡名当作「鹰身女郎」使用。这只怪兽战斗破坏的反转效果怪兽的效果无效化。'),
(54415063, 'Harpie Lady 3', '鹰身女郎3', 'ハーピィ・レディ３', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1300, 1400, '这张卡的卡名当作「鹰身女郎」使用。和这张卡发生战斗的对方怪兽，此怪兽在对方的2个回合内攻击宣言不能。'),
(65664792, 'Harpie Lady Elegance', '华丽的神鹰女郎', '華麗なるハーピィ・レディ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：选自己场上1只「鹰身女郎三姐妹」回到持有者卡组。那之后，可以把3只原本卡名不同的「鹰身」怪兽从自己的手卡·卡组·墓地各选1只特殊召唤。这张卡的发动后，直到回合结束时自己不是风属性怪兽不能特殊召唤。 ②：场上的这张卡被对方的效果或者自己的「鹰身」卡的效果破坏的场合发动。从卡组把1只「鹰身」怪兽加入手卡。'),
(86308219, 'Harpie Lady Phoenix Formation', '神鹰女郎 －凤凰之阵－', 'ハーピィ・レディ －鳳凰の陣－', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能从卡组·额外卡组把怪兽特殊召唤，不能进行战斗阶段。 ①：自己场上有「鹰身女郎」「鹰身女郎三姐妹」合计3只以上存在的场合，尽可能以最多有那个数量的对方场上的怪兽为对象才能发动。作为对象的怪兽破坏，给与对方破坏的怪兽之内原本攻击力最高的怪兽的那个数值的伤害。'),
(12206212, 'Harpie Lady Sisters', '神鹰女郎三姐妹', 'ハーピィ・レディ三姉妹', 'Effect Monster', 'Winged Beast', 'WIND', 6, 1950, 2100, '这张卡不能通常召唤。「万华镜-华丽的分身-」的效果可以特殊召唤。'),
(66386380, 'Harpie Oracle', '神鹰预见师', 'ハーピィ・オラクル', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1300, 1400, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「鹰身女郎」使用。 ②：自己场上有5星以上的「鹰身」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ③：这张卡召唤·特殊召唤成功的场合才能发动。这个回合的结束阶段，从自己墓地选有「鹰身女郎三姐妹」的卡名记述的1张魔法·陷阱卡加入手卡。'),
(39392286, 'Harpie Perfumer', '神鹰调香师', 'ハーピィ・パフューマー', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1400, 1300, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「鹰身女郎」使用。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把有「鹰身女郎三姐妹」的卡名记述的1张魔法·陷阱卡加入手卡。自己场上有5星以上的「鹰身」怪兽存在的状态把这个效果发动的场合，这个效果加入手卡的数量可以变成2张（同名卡最多1张）。'),
(75064463, 'Harpie Queen', '神鹰女王', 'ハーピィ・クィーン', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1900, 1200, '①：这张卡的卡名只要在场上·墓地存在当作「鹰身女郎」使用。 ②：把这张卡从手卡丢弃去墓地才能发动。从卡组把1张「鹰身女妖的狩猎场」加入手卡。'),
(18144507, 'Harpie''s Feather Duster', '神鹰羽毛扫', 'ハーピィの羽根帚', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(39275698, 'Harpie''s Feather Rest', '神鹰羽毛休憩', 'ハーピィの羽根休め', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己墓地的「鹰身女郎」「鹰身女郎三姐妹」之中以合计3只为对象才能发动。那些卡加入卡组洗切。那之后，自己从卡组抽1张。自己场上有5星以上的「鹰身」怪兽存在的状态发动的场合抽出的数量变成2张。这张卡的发动后，直到回合结束时自己不是风属性怪兽不能特殊召唤。'),
(87639778, 'Harpie''s Feather Storm', '神鹰羽毛吹雪', 'ハーピィの羽根吹雪', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有「鹰身」怪兽存在的场合，这张卡的发动从手卡也能用。 ①：自己场上有鸟兽族·风属性怪兽存在的场合才能发动。直到回合结束时，对方发动的怪兽的效果无效化。 ②：魔法与陷阱区域的这张卡被对方的效果破坏的场合才能发动。从自己的卡组·墓地选1张「鹰身女妖的羽毛扫」加入手卡。'),
(6924874, 'Harpie''s Pet Baby Dragon', '鹰身女妖的宠物仔龙', 'ハーピィズペット仔竜', 'Effect Monster', 'Dragon', 'WIND', 4, 1200, 600, '这张卡追加自己场上存在的除「鹰身女妖的宠物仔龙」以外的名字带有「鹰身」的怪兽的数量的效果。 ●1只：只要这张卡在场上表侧表示存在，对方不能选择自己场上存在的除「鹰身女妖的宠物仔龙」以外的名字带有「鹰身」的怪兽作为攻击对象。 ●2只：这张卡的原本攻击力·守备力变成2倍。 ●3只：1回合1次，可以把对方场上的1张卡破坏。'),
(52040216, 'Harpie''s Pet Dragon', '神鹰的宠物龙', 'ハーピィズペット竜', 'Effect Monster', 'Dragon', 'WIND', 7, 2000, 2500, '①：这张卡的攻击力·守备力上升场上的「鹰身女郎」数量×300。'),
(4991081, 'Harpie''s Pet Dragon - Fearsome Fire Blast', '神鹰的宠物龙－千兆圣火', 'ハーピィズペット竜－セイント・ファイアー・ギガ', 'Effect Monster', 'Dragon', 'WIND', 7, 2000, 2500, '这个卡名的①③的效果1回合各能使用1次。 ①：自己场上有6星以下的风属性怪兽存在的场合才能发动。这张卡从手卡守备表示特殊召唤。 ②：只要这张卡在怪兽区域存在，双方怪兽不能选择6星以下的「鹰身」怪兽作为攻击对象。 ③：这张卡从场上送去墓地的场合才能发动。从卡组把1只鸟兽族·风属性怪兽送去墓地。'),
(85909450, 'Harpie''s Pet Phantasmal Dragon', '神鹰的宠物幻龙', 'ハーピィズペット幻竜', 'XYZ Monster', 'Dragon', 'WIND', 4, 2000, 2500, '风属性4星怪兽×3 这张卡的效果若这张卡的超量素材没有则不适用。这张卡可以直接攻击对方玩家。只要这张卡在场上表侧表示存在，对方不能把名字带有「鹰身」的怪兽作为攻击对象，也不能作为卡的效果的对象。每次自己的结束阶段把这张卡1个超量素材取除。'),
(75782277, 'Harpies'' Hunting Ground', '神鹰狩猎场', 'ハーピィの狩場', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的鸟兽族怪兽的攻击力·守备力上升200。 ②：自己或对方把「鹰身女郎」或「鹰身女郎三姐妹」召唤·特殊召唤的场合，那玩家以场上1张魔法·陷阱卡为对象发动。那张卡破坏。'),
(68199168, 'Harr, Generaider Boss of Storms', '轰之创王 哈尔', '轟の王 ハール', 'Effect Monster', 'Spellcaster', 'DARK', 9, 3000, 3000, '这个卡名的③的效果1回合只能使用1次。 ①：「轰界王战 哈尔王」在自己场上只能有1只表侧表示存在。 ②：1回合1次，对方在抽卡阶段以外从卡组把卡加入手卡的场合才能发动。对方必须把自身的手卡·场上1只怪兽送去墓地。 ③：魔法·陷阱·怪兽的效果发动时，把自己场上的「王战」怪兽或者魔法师族怪兽合计2只解放才能发动。那个发动无效并破坏。'),
(31987203, 'Harvest Angel of Doom', '死天使 哈贝斯特', '死天使ハーヴェスト', 'Pendulum Effect Monster', 'Fairy', 'DARK', 4, 1800, 1000, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：这张卡召唤·灵摆召唤成功的场合才能发动。从卡组把1张「升天之角笛」加入手卡。 ②：这张卡被解放的场合才能发动。这张卡在自己的灵摆区域放置。'),
(85399281, 'Harvest Angel of Wisdom', '智天使 哈维斯特', '智天使ハーヴェスト', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1800, 1000, '①：这张卡被战斗破坏送去墓地时，以自己墓地1张反击陷阱卡为对象才能发动。那张卡加入手卡。'),
(93895605, 'Hate Buster', '仇恨炸弹', 'ヘイト・バスター', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的恶魔族怪兽被选择作为攻击对象时，以1只攻击怪兽和那1只攻击对象怪兽为对象才能发动。那只攻击怪兽和那只攻击对象怪兽2只破坏，给与对方破坏的攻击怪兽的原本攻击力数值的伤害。'),
(43618262, 'Hatsugai', '初买', '初買い', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从对方卡组上面把5张卡翻开，自己从那之中选1张并宣言100的倍数的数值（最多3000）。对方可以回复那个数值的基本分。回复的场合，自己失去那个数值的基本分，选的卡加入自己手卡，剩下的卡用原本的顺序回到卡组上面。没回复的场合，翻开的卡用原本的顺序回到卡组上面。'),
(39033131, 'Haunted Shrine', '妖怪筑巢的祠堂', 'もののけの巣くう祠', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上没有怪兽存在的场合，以自己墓地1只不死族怪兽为对象才能发动。那只怪兽特殊召唤。 ②：自己场上没有怪兽存在的场合，把墓地的这张卡除外，以自己墓地1只不死族怪兽为对象才能发动。那只怪兽效果无效特殊召唤。'),
(32335697, 'Haunted Zombies', '闹鬼不死族', 'ホーンテッド・アンデット', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从自己或者对方的墓地选1只不死族怪兽除外，把持有和那个等级相同等级的2只「祟灵衍生物」（不死族·暗·攻/守0）在自己场上特殊召唤。 ②：这张卡在墓地存在的场合才能发动。选除外的1只自己的不死族怪兽回到卡组，这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(21015833, 'Hayabusa Knight', '隼骑士', '隼の騎士', 'Effect Monster', 'Warrior', 'EARTH', 3, 1000, 700, '①：这张卡在同1次的战斗阶段中可以作2次攻击。'),
(7443908, 'Hayate the Earth Star', '地翔星 疾风', '地翔星ハヤテ', 'Effect Monster', 'Warrior', 'EARTH', 5, 2100, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：在只有对方场上才有怪兽存在的场合或者在自己场上有光属性怪兽存在的场合，这张卡可以不用解放作召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从手卡把1只战士族·光属性·5星怪兽特殊召唤。 ③：1回合1次，自己的战士族怪兽被选择作为攻击对象时才能发动。这张卡的攻击力下降500，那次攻击无效。'),
(23776077, 'Hazy Flame Basiltrice', '阳炎兽 巴西利科克', '陽炎獣 バジリコック', 'XYZ Monster', 'Pyro', 'FIRE', 6, 2500, 1800, '炎属性6星怪兽×2只以上（最多5只） 1回合1次，把这张卡1个超量素材取除才能发动。选择对方的场上·墓地1只怪兽从游戏中除外。此外，这张卡持有的超量素材数量让这张卡得到以下效果。 ●3个以上：这张卡的攻击力·守备力上升这张卡的超量素材数量×200的数值。 ●4个以上：这张卡不会成为对方的卡的效果的对象。 ●5个：这张卡不会被卡的效果破坏。'),
(38525760, 'Hazy Flame Cerbereus', '阳炎兽 刻耳柏洛斯', '陽炎獣 サーベラス', 'Effect Monster', 'Beast', 'FIRE', 6, 2000, 200, '这张卡可以不用解放作召唤。这个方法召唤的这张卡的原本攻击力变成1000。只要这张卡在场上表侧表示存在，对方不能把这张卡作为卡的效果的对象。此外，这张卡被破坏送去墓地时，可以从卡组把1张名字带有「阳炎」的卡加入手卡。'),
(74010769, 'Hazy Flame Griffin', '阳炎兽 狮鹫', '陽炎獣 グリプス', 'Effect Monster', 'Winged Beast', 'FIRE', 6, 200, 2100, '对方场上有怪兽存在，自己的场上·墓地没有炎属性以外的怪兽存在的场合，这张卡可以从手卡特殊召唤。只要这张卡在场上表侧表示存在，对方不能把这张卡作为卡的效果的对象。'),
(8696773, 'Hazy Flame Hydra', '阳炎兽 许德拉', '陽炎獣 ヒュドラー', 'Effect Monster', 'Dinosaur', 'FIRE', 6, 2300, 200, '只要这张卡在场上表侧表示存在，对方不能把这张卡作为卡的效果的对象，自己不能把炎属性以外的怪兽特殊召唤。此外，这张卡为素材的超量怪兽得到以下效果。 ●这次超量召唤成功时，可以从自己墓地选择1只名字带有「阳炎兽」的怪兽在这张卡下面重叠作为超量素材。'),
(31303283, 'Hazy Flame Hyppogrif', '阳炎兽 骏鹰', '陽炎獣 ヒッポグリフォ', 'Effect Monster', 'Pyro', 'FIRE', 6, 2100, 200, '只要这张卡在场上表侧表示存在，对方不能把这张卡作为卡的效果的对象。此外，1回合1次，把自己场上1只炎属性怪兽解放才能发动。这张卡的攻击力上升300。'),
(96051150, 'Hazy Flame Mantikor', '阳炎兽 蝎狮', '陽炎獣 メコレオス', 'Effect Monster', 'Winged Beast', 'FIRE', 6, 2200, 300, '只要这张卡在场上表侧表示存在，对方不能把这张卡作为卡的效果的对象。此外，1回合1次，把手卡或者自己场上表侧表示存在的1只炎属性怪兽送去墓地才能发动。这个回合，这张卡不会被卡的效果破坏。这个效果在对方回合也能发动。'),
(37803172, 'Hazy Flame Peryton', '阳炎兽 佩利冬', '陽炎獣 ペリュトン', 'Effect Monster', 'Pyro', 'FIRE', 6, 1600, 1700, '这张卡不能用名字带有「阳炎兽」的怪兽的效果以外特殊召唤。只要这张卡在场上表侧表示存在，对方不能把这张卡作为卡的效果的对象。此外，把手卡1只炎属性怪兽送去墓地，把这张卡解放才能发动。从卡组把2只名字带有「阳炎兽」的怪兽特殊召唤。「阳炎兽 佩利冬」的这个效果1回合只能使用1次。'),
(1409474, 'Hazy Flame Sphynx', '阳炎兽 斯芬克司', '陽炎獣 スピンクス', 'Effect Monster', 'Beast-Warrior', 'FIRE', 6, 1900, 1900, '只要这张卡在场上表侧表示存在，对方不能把这张卡作为卡的效果的对象。此外，自己的主要阶段时，宣言卡的种类（怪兽·魔法·陷阱）才能发动。自己卡组最上面的卡送去墓地，宣言的种类的卡的场合，可以再从自己的手卡·墓地选1只炎属性怪兽特殊召唤。「阳炎兽 斯芬克司」的这个效果1回合只能使用1次。'),
(43708041, 'Hazy Glory', '阳炎光轮', '陽炎光輪', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，自己可以把名字带有「阳炎兽」的怪兽召唤的场合需要的解放减少1只。此外，可以通过把场上表侧表示存在的这张卡送去墓地，从自己墓地选择「阳炎光轮」以外的1张名字带有「阳炎」的卡加入手卡。'),
(83108603, 'Hazy Pillar', '阳炎柱', '陽炎柱', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，自己可以把名字带有「阳炎兽」的怪兽召唤的场合需要的解放减少1只。此外，1回合1次，选择自己场上1只超量怪兽才能发动。把自己的手卡·场上1只名字带有「阳炎兽」的怪兽在选择的超量怪兽下面重叠作为超量素材。'),
(38143903, 'Head Judging', '头位审判', 'ヘッド・ジャッジング', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己或者对方把场上的怪兽的效果发动时才能发动。发动的那个玩家进行1次投掷硬币，对里表作猜测。猜中的场合，这张卡送去墓地。猜错的场合，那个发动无效，那只怪兽的控制权移给从那个玩家来看的对方。'),
(5434080, 'Headless Knight', '无头骑士', '首なし騎士', 'Normal Monster', 'Fiend', 'EARTH', 4, 1450, 1700, '被判决为反叛者遭处刑的骑士的亡灵，为寻找失去的东西，无论遇到谁都会受到他的攻击。'),
(31281980, 'Healing Wave Generator', '治愈波镜', 'ヒール・ウェーバー', 'Effect Monster', 'Machine', 'LIGHT', 4, 800, 1600, '选择这张卡以外的自己场上表侧表示存在的1只怪兽发动。回复选择怪兽的等级×100的数值的基本分。这个效果1回合只能使用1次。'),
(64801562, 'Heart of Clear Water', '明镜止水之心', '明鏡止水の心', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备这张卡的怪兽攻击力1300以上的场合这张卡破坏。这张卡装备的怪兽，不会被战斗和以那只怪兽为对象的卡的效果破坏。（仍然计算伤害）'),
(54475145, 'Heart of the Blue-Eyes', '寄托于心的青眼龙', '心宿りし青眼竜', 'Effect Monster', 'Dragon', 'LIGHT', 8, 3000, 2500, '这个卡名在规则上也当作「千年」卡使用。这个卡名的①的效果1回合只能使用1次，③的效果在自己把「千年十字」发动的决斗中才能使用1次。 ①：把这张卡从手卡丢弃才能发动。从卡组把1张「千年十字」加入手卡。 ②：这张卡的控制权不能变更。 ③：这张卡在墓地存在的状态，对方把8星以上或攻击力3000以上的怪兽召唤·特殊召唤的场合才能发动。那些怪兽送去墓地，这张卡特殊召唤。'),
(35762283, 'Heart of the Underdog', '凡骨的意志', '凡骨の意地', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '当抽卡阶段抽到的卡是通常怪兽的场合，向对方展示抽到的卡，就可以再抽1张卡。'),
(32065885, 'Heartfelt Appeal', '痛恨的诉苦', '痛恨の訴え', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的直接攻击让自己受到战斗伤害时才能发动。对方场上表侧表示存在的1只守备力最高的怪兽的控制权直到下次的自己的结束阶段时得到。这个效果得到控制权的怪兽的效果无效化，也不能攻击宣言。'),
(47439573, 'Heartless Drop Off', '无情的打落', '無情なはたき落とし', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：场上的表侧表示的卡或者墓地的卡因效果加入对方手卡时才能发动。把对方手卡确认，从那之中把加入手卡的卡以及那些同名卡全部除外。'),
(45141013, 'Heat Wave', '大热波', '大熱波', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己主要阶段1开始时才能发动。直到下次的自己抽卡阶段，双方不能把效果怪兽召唤·特殊召唤。'),
(51684157, 'Heavenly Dragon Circle', '天幻龙轮', '天幻の龍輪', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把自己场上1只幻龙族怪兽解放才能发动。从卡组把1只幻龙族怪兽加入手卡。把效果怪兽以外的怪兽解放来把这张卡发动的场合，也能不加入手卡把效果无效特殊召唤。 ②：自己场上有效果怪兽以外的表侧表示怪兽存在的场合，自己主要阶段把墓地的这张卡除外才能发动。从卡组把1张「天威」卡加入手卡。'),
(17255673, 'Heavenly Gate of the Mikanko', '天御巫之阖', '天御巫の闔', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要有装备卡装备的怪兽在自己场上存在，可以攻击的对方怪兽必须向有装备卡装备的怪兽作出攻击。 ②：自己的「御巫」怪兽进行战斗的场合，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。 ③：自己的「御巫」怪兽进行攻击的伤害步骤结束时，把自己场上1张装备卡送去墓地才能发动。那只怪兽向对方怪兽可以继续攻击。');